package com.bank.combo.service;

import java.util.logging.Logger;

// Counts how many subsets of charges sum exactly to a target (0/1 counting DP).
public class CombinationCountService {
    private static final Logger log = Logger.getLogger(CombinationCountService.class.getName());

    public long countSubsets(int[] charges, int target) {
        if (target < 0) return 0;
        long[] dp = new long[target + 1];
        dp[0] = 1;                                  // one empty subset sums to 0
        for (int c : charges) {
            for (int t = target; t >= c; t--) {     // high → low ⇒ each charge once
                dp[t] += dp[t - c];                 // add counts, don't OR
            }
        }
        log.info(() -> "Subsets summing to " + target + " = " + dp[target]);
        return dp[target];
    }
}
