package com.bank.combo;

import com.bank.combo.service.CombinationCountService;
import java.util.logging.Logger;

public class CombinationCountApplication {
    private static final Logger log = Logger.getLogger(CombinationCountApplication.class.getName());

    public static void main(String[] args) {
        CombinationCountService service = new CombinationCountService();
        int[] charges = {1, 1, 2, 3};       // individual charges (thousands)
        int target = 4;
        long count = service.countSubsets(charges, target);
        log.info("Number of charge combinations summing to " + target + ": " + count);
    }
}
